            throw new ArgumentException("Draw01 fixed widening requires the original main-mesh vertex layout.");
        var groups = lod switch { 0 => Near, 1 => Middle, 2 => Far, _ => throw new ArgumentOutOfRangeException(nameof(lod)) };
